import Bogenzeit
import Foundation
import XCTest

/// The golden vectors in vectors/bz_vectors.json, generated by the Python
/// reference: event times within one second, displayed values exact.
final class VectorTests: XCTestCase {
    func testEveryVectorPasses() throws {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("vectors/bz_vectors.json")
        let file = try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as! [String: Any]
        let vectors = file["vectors"] as! [[String: Any]]
        XCTAssertFalse(vectors.isEmpty)
        for v in vectors {
            let name = v["name"] as! String
            let t = Date(rfc3339: v["utc"] as! String)!
            let r = Reading(at: t, latitude: v["lat"] as! Double, longitude: v["lon"] as! Double)
            let e = v["expected"] as! [String: Any]
            let day = r.day

            XCTAssertEqual(day.day.description, e["bz_date"] as? String, "\(name): bz_date")
            instantWithin(name, "solar_noon_utc", day.noon, e)
            instantWithin(name, "solar_midnight_start_utc", day.midnightStart, e)
            instantWithin(name, "solar_midnight_end_utc", day.midnightEnd, e)
            XCTAssertEqual(r.anchor.name, e["anchor"] as? String, "\(name): anchor")
            XCTAssertEqual(r.offset, e["offset_s"] as! Double, accuracy: 1, "\(name): offset_s")
            XCTAssertEqual(r.displayOffsetKs, e["display_offset_ks"] as! Double, "\(name): display_offset_ks")

            if let polar = e["polar"] as? String {
                XCTAssertEqual(r.polar?.name, polar, "\(name): polar")
                XCTAssertNil(r.span, "\(name): polar has no span")
                XCTAssertNil(r.eighth, "\(name): polar has no eighth")
                continue
            }
            instantWithin(name, "sunrise_utc", day.sunrise!, e)
            instantWithin(name, "sunset_utc", day.sunset!, e)
            XCTAssertEqual(day.tagbogen!, e["tagbogen_s"] as! Double, accuracy: 1, "\(name): tagbogen_s")
            if let halfNight = e["half_night_s"] as? Double {
                XCTAssertEqual(r.spanSeconds! * 100, halfNight, accuracy: 1, "\(name): half_night_s")
            }
            XCTAssertEqual(r.span!, e["span"] as! Double, accuracy: 0.001, "\(name): span")
            XCTAssertEqual(r.displaySpan, e["display_span"] as? Int, "\(name): display_span")
            XCTAssertEqual(r.eighth?.name, e["eighth"] as? String, "\(name): eighth")
            XCTAssertEqual(r.combinedForm, e["written"] as? String, "\(name): written")
            XCTAssertEqual(r.spanForm, e["written_span"] as? String, "\(name): written_span")
        }
    }

    func testEveryDurationPasses() throws {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("vectors/bz_vectors.json")
        let file = try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as! [String: Any]
        let durations = file["durations"] as! [[String: Any]]
        XCTAssertFalse(durations.isEmpty)
        for v in durations {
            let name = v["name"] as! String
            let d = SolarDuration(
                from: Date(rfc3339: v["from"] as! String)!,
                to: Date(rfc3339: v["to"] as! String)!,
                latitude: v["lat"] as! Double,
                longitude: v["lon"] as! Double)
            let e = v["expected"] as! [String: Any]
            XCTAssertEqual(d.seconds, e["seconds"] as! Double, accuracy: 1, "\(name): seconds")
            XCTAssertEqual(Double(d.displayKsSteps) / 10, e["display_ks"] as! Double, "\(name): display_ks")
            if let spans = e["spans"] as? Double {
                XCTAssertEqual(d.spans!, spans, accuracy: 0.001, "\(name): spans")
                XCTAssertEqual(d.displaySpans, e["display_spans"] as? Int, "\(name): display_spans")
            } else {
                XCTAssertNil(d.spans, "\(name): spans across a polar day")
            }
        }
    }

    func testEveryInstantPasses() throws {
        let instants = try vectorFile()["instants"] as! [[String: Any]]
        XCTAssertFalse(instants.isEmpty)
        for v in instants {
            let day = SolarDay(
                CalendarDay(v["bz_date"] as! String)!,
                latitude: (v["lat"] as! NSNumber).doubleValue,
                longitude: (v["lon"] as! NSNumber).doubleValue)
            let actual = day.instant(atPlace: (v["place"] as! NSNumber).doubleValue)
            expectedInstant(v["name"] as! String, actual, v["expected"] as! [String: Any])
        }
    }

    func testEveryAdvancePasses() throws {
        let advances = try vectorFile()["advances"] as! [[String: Any]]
        XCTAssertFalse(advances.isEmpty)
        for v in advances {
            let reading = Reading(
                at: Date(rfc3339: v["from"] as! String)!,
                latitude: (v["lat"] as! NSNumber).doubleValue,
                longitude: (v["lon"] as! NSNumber).doubleValue)
            let actual = reading.after(spans: (v["spans"] as! NSNumber).doubleValue)
            expectedInstant(v["name"] as! String, actual, v["expected"] as! [String: Any])
        }
    }

    private func vectorFile() throws -> [String: Any] {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("vectors/bz_vectors.json")
        return try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as! [String: Any]
    }

    private func expectedInstant(_ name: String, _ actual: Date?, _ expected: [String: Any]) {
        guard expected["utc"] is String else {
            XCTAssertNil(actual, "\(name): no instant on a polar day")
            return
        }
        guard let actual else { return XCTFail("\(name): no instant") }
        instantWithin(name, "utc", actual, expected)
    }

    private func instantWithin(_ name: String, _ field: String, _ actual: Date, _ expected: [String: Any]) {
        let expected = Date(rfc3339: expected[field] as! String)!
        XCTAssertEqual(actual.timeIntervalSince(expected), 0, accuracy: 1, "\(name): \(field)")
    }
}
